--
-- Table structure for table `catalog_search_documents`
--

DROP TABLE IF EXISTS `catalog_search_documents`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `catalog_search_documents` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint unsigned NOT NULL,
  `code` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `normalized_code` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name` varchar(512) COLLATE utf8mb4_unicode_ci NOT NULL,
  `category_id` bigint unsigned DEFAULT NULL,
  `category_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `brand` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `model` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `condition` varchar(16) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `list_price` decimal(12,2) DEFAULT NULL,
  `has_image` tinyint(1) NOT NULL DEFAULT '0',
  `duplicate_code` tinyint(1) NOT NULL DEFAULT '0',
  `attributes` json DEFAULT NULL,
  `equivalences` json DEFAULT NULL,
  `searchable_text` longtext COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_hash` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `catalog_search_documents_product_id_unique` (`product_id`),
  KEY `catalog_search_documents_code_index` (`code`),
  KEY `catalog_search_documents_normalized_code_index` (`normalized_code`),
  KEY `catalog_search_documents_category_id_index` (`category_id`),
  KEY `catalog_search_documents_brand_index` (`brand`),
  KEY `catalog_search_documents_content_hash_index` (`content_hash`),
  FULLTEXT KEY `ft_searchable` (`searchable_text`,`name`)
) ENGINE=InnoDB AUTO_INCREMENT=5055 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

